"""Deployment settings and shared helpers."""

import json
import secrets
import sys
from pathlib import Path

import boto3
from botocore.config import Config

ROOT = Path(__file__).resolve().parent.parent
REGION = "us-west-2"  # the bucket is created in the same region as the runtime
NAME = "s3mount-isolation"
STACK_NAME = NAME
RUNTIME_NAME = NAME.replace("-", "_")
STATE_FILE = ROOT / f".state-{REGION}.json"  # outputs, image, runtime ARN and the agencies' session IDs
MODEL_ID = "us.anthropic.claude-opus-5-5"

# Shared market data, generated by infra/data_gen.py into s3://<bucket>/datasets/market/: synthetic NYC
# rental listings, 24M rows (~340 MB of Parquet). Same seed, same files.
DATA_GEN = {"first_month": "2024-01", "months": 24, "rows_per_month": 1_000_000, "seed": 20261117}

# The two users of the sample: rental agencies, each with a private portfolio of its own listings
# (also generated) under s3://<bucket>/users/<its session id>/. All names are fictional.
AGENCIES = {
    "acme": {"name": "Acme Realty", "boroughs": ["Manhattan", "Brooklyn"], "price_vs_market": 1.06, "listings": 3000},
    "brooklynhomes": {"name": "Brooklyn Homes", "boroughs": ["Brooklyn"], "price_vs_market": 0.97, "listings": 2000},
}


def log(msg: str) -> None:
    print(f"\033[1;36m[{NAME}]\033[0m {msg}", file=sys.stderr, flush=True)


def die(msg: str):
    print(f"\033[1;31m[{NAME}]\033[0m {msg}", file=sys.stderr, flush=True)
    raise SystemExit(1)


def client(service: str, read_timeout: int = 60):
    return boto3.client(service, region_name=REGION,
                        config=Config(read_timeout=read_timeout, retries={"max_attempts": 3, "mode": "standard"}))


def load_state() -> dict:
    return json.loads(STATE_FILE.read_text()) if STATE_FILE.exists() else {}


def save_state(state: dict) -> None:
    STATE_FILE.write_text(json.dumps(state, indent=2) + "\n")


def session_id(agency: str) -> str:
    """The user-to-session mapping, the one piece a real backend owns (a table keyed by user, written at
    sign-up). AgentCore doesn't know users: it isolates sessions, so whoever picks the session ID picks
    whose data the session reaches. The ID must therefore be unguessable and known only to the backend:
    a random value, created once per agency and kept in the local state file (never committed). Each
    agency keeps the same ID, so its private prefix users/<session id>/ is the same in every
    conversation. Format per the AgentCore docs: one segment of 33-256 letters, digits, '_' or '-'."""
    if agency not in AGENCIES:
        raise SystemExit(f"unknown agency {agency!r}; choose one of {', '.join(AGENCIES)}")
    state = load_state()
    sessions = state.setdefault("sessions", {})
    if agency not in sessions:
        sessions[agency] = f"agency-{agency}-{secrets.token_hex(24)}"
        save_state(state)
    return sessions[agency]


def stack_outputs(stack_name: str = STACK_NAME) -> dict:
    cfn = client("cloudformation")
    try:
        stack = cfn.describe_stacks(StackName=stack_name)["Stacks"][0]
    except cfn.exceptions.ClientError as e:
        if "does not exist" in str(e):
            return {}
        raise
    return {o["OutputKey"]: o["OutputValue"] for o in stack.get("Outputs", [])}


def find_runtime(ctl=None, name: str = RUNTIME_NAME) -> dict | None:
    ctl = ctl or client("bedrock-agentcore-control")
    for page in ctl.get_paginator("list_agent_runtimes").paginate():
        for rt in page.get("agentRuntimes", []):
            if rt.get("agentRuntimeName") == name:
                return rt
    return None
